#!/usr/bin/env python3
import json,csv,statistics as st,math,sys,hashlib
from pathlib import Path
from datetime import datetime, timezone
R=Path(sys.argv[1]); O=R/'report'; O.mkdir(exist_ok=True)
profiles=['decode','prefill','balanced']; rows=[]
def av(d,k,s='avg'):
 x=d.get(k,{}); return x.get(s) if isinstance(x,dict) else None
def vsum(d,k):
 xs=[x.get('avg') for x in d.get(k,{}).get('series',[]) if isinstance(x.get('avg'),(int,float))]; return sum(xs) if xs else None
for f in sorted(R.glob('runs/*/c*/run-r*/profile_export_aiperf.json')):
 d=json.load(open(f)); rd=f.parent; m=json.load(open(rd/'manifest.json')); vm=json.load(open(rd/'victoriametrics/summary.json'))
 p=m['workload']['profile']; c=m['workload']['global_concurrency']; dur=av(d,'benchmark_duration'); pw=av(vm,'gpu_power')*8 if av(vm,'gpu_power') is not None else None
 draft=vsum(vm,'vllm_mtp_draft_rate'); acc=vsum(vm,'vllm_mtp_accepted_rate')
 row={'profile':p,'concurrency':c,'repetition':m['workload']['repetition'],'run_id':m['run_id'],'requests':av(d,'request_count'),'errors':len(d.get('error_summary') or []),'duration_s':dur,
 'actual_isl':av(d,'input_sequence_length'),'actual_osl':av(d,'output_sequence_length'),'input_tps':av(d,'input_token_throughput'),'decode_tps':av(d,'output_token_throughput'),'total_tps':av(d,'total_token_throughput'),'per_user_tps':av(d,'output_token_throughput_per_user'),
 'ttft_p50_ms':av(d,'time_to_first_token','p50'),'ttft_p95_ms':av(d,'time_to_first_token','p95'),'ttft_p99_ms':av(d,'time_to_first_token','p99'),'itl_avg_ms':av(d,'inter_token_latency'),'itl_p95_ms':av(d,'inter_token_latency','p95'),'e2e_p50_ms':av(d,'request_latency','p50'),'e2e_p95_ms':av(d,'request_latency','p95'),
 'cpu_busy_pct':av(vm,'node_cpu_busy_ratio')*100,'cpu_user_pct':av(vm,'node_cpu_user_ratio')*100,'cpu_system_pct':av(vm,'node_cpu_system_ratio')*100,'cpu_iowait_pct':av(vm,'node_cpu_iowait_ratio')*100,'load1':av(vm,'node_load1'),'ram_used_gib':av(vm,'node_memory_used_bytes')/2**30,'ram_available_gib':av(vm,'node_memory_available_bytes')/2**30,'swap_used_gib':av(vm,'node_swap_used_bytes')/2**30,
 'gpu_util_pct':av(vm,'gpu_utilization'),'gpu_memcopy_pct':av(vm,'gpu_memory_copy_utilization'),'gpu_temp_c':av(vm,'gpu_temperature'),'gpu_vram_used_gib':av(vm,'gpu_memory_used')*8/1024,'gpu_power_w':pw,'gpu_energy_j':pw*dur,'gpu_j_per_output_token':pw*dur/av(d,'total_osl') if av(d,'total_osl') else None,'gpu_j_per_input_token':pw*dur/av(d,'total_isl') if av(d,'total_isl') else None,'gpu_sm_clock_mhz':av(vm,'gpu_sm_clock'),'gpu_mem_clock_mhz':av(vm,'gpu_memory_clock'),
 'container_cpu_cores':vsum(vm,'container_cpu_rate'),'container_memory_gib':vsum(vm,'container_memory')/2**30 if vsum(vm,'container_memory') else None,'container_rx_mib_s':vsum(vm,'container_network_rx_rate')/2**20 if vsum(vm,'container_network_rx_rate') else None,'container_tx_mib_s':vsum(vm,'container_network_tx_rate')/2**20 if vsum(vm,'container_network_tx_rate') else None,
 'running_requests':vsum(vm,'vllm_running_requests'),'waiting_requests':vsum(vm,'vllm_waiting_requests'),'kv_cache_pct':av(vm,'vllm_kv_cache_usage')*100,'preemptions_s':vsum(vm,'vllm_preemptions_rate'),'mtp_acceptance_pct':100*acc/draft if draft else None,'prompt_rate':vsum(vm,'vllm_prompt_tokens_rate'),'generation_rate':vsum(vm,'vllm_generation_tokens_rate'),
 'disk_read_mib_s':av(vm,'disk_read_bytes_rate')/2**20,'disk_write_mib_s':av(vm,'disk_write_bytes_rate')/2**20,'host_rx_mib_s':av(vm,'network_receive_bytes_rate')/2**20,'host_tx_mib_s':av(vm,'network_transmit_bytes_rate')/2**20}
 rows.append(row)
# aggregate all source profiles
metrics=[k for k in rows[0] if k not in ('profile','concurrency','repetition','run_id','errors')]
agg=[]
for p in profiles:
 for c in sorted({r['concurrency'] for r in rows if r['profile']==p}):
  rs=[r for r in rows if r['profile']==p and r['concurrency']==c]; a={'profile':p,'concurrency':c,'n':len(rs),'errors':sum(r['errors'] for r in rs)}
  for k in metrics:
   xs=[r[k] for r in rs if isinstance(r.get(k),(int,float)) and math.isfinite(r[k])]
   if xs:
    a[k+'_mean']=st.fmean(xs);a[k+'_median']=st.median(xs);a[k+'_min']=min(xs);a[k+'_max']=max(xs);a[k+'_sd']=st.stdev(xs) if len(xs)>1 else 0
  agg.append(a)
# independently choose strongest profile family
byprof={p:[a for a in agg if a['profile']==p] for p in profiles}
dec_prof=max(profiles,key=lambda p:max(a['decode_tps_median'] for a in byprof[p])); pre_prof=max(profiles,key=lambda p:max(a['input_tps_median'] for a in byprof[p]))
selected=[]
for kind,p in [('decode',dec_prof),('prefill',pre_prof)]:
 for a in byprof[p]:
  q=dict(a);q['kind']=kind;q.pop('profile');selected.append(q)
selected.sort(key=lambda x:(x['kind'],x['concurrency']))
# idle baseline from campaign-wide GPU CSV and timestamp files
def dt(s): return datetime.fromisoformat(s.strip().replace(',','.').replace('Z','+00:00'))
def idle_window(tag):
 a=dt((R/'idle'/f'{tag}-start.txt').read_text());b=dt((R/'idle'/f'{tag}-end.txt').read_text()); vals=[]
 with open(R/'campaign-resource-gpu.csv') as f:
  for q in csv.DictReader(f):
   try:
    t=datetime.strptime(q['timestamp'],'%Y/%m/%d %H:%M:%S.%f').replace(tzinfo=timezone.utc)
    if a<=t<=b: vals.append(float(q['power_w']))
   except: pass
 return st.fmean(vals)*8 if vals else None
preidle=idle_window('pre');postidle=idle_window('post');idle=st.fmean([x for x in [preidle,postidle] if x])
# exports
with open(O/'campaign-summary-runs.csv','w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
keys=sorted(set().union(*(a.keys() for a in agg)),key=lambda x:(x not in ('profile','concurrency','n','errors'),x))
with open(O/'campaign-summary-aggregate.csv','w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=keys);w.writeheader();w.writerows(agg)
meta={'generated_utc':datetime.now(timezone.utc).isoformat(),'source':str(R),'source_runs':len(rows),'source_requests':sum(r['requests'] or 0 for r in rows),'source_errors':sum(r['errors'] for r in rows),'selected_decode_source':dec_prof,'selected_prefill_source':pre_prof,'selected_runs':sum(1 for x in rows if x['profile'] in {dec_prof,pre_prof}),'idle_power_w':idle,'rows':rows,'aggregate':agg,'selected':selected}
json.dump(meta,open(O/'campaign-summary.json','w'),indent=2)
bd=max((x for x in selected if x['kind']=='decode'),key=lambda x:x['decode_tps_median']);bp=max((x for x in selected if x['kind']=='prefill'),key=lambda x:x['input_tps_median'])
DATA=json.dumps(selected,separators=(',',':'))
